// ─── HELPERS ───────────────────────────────────────────────
const MT = ({c=C.t3,children,sp=2.5}) => (
  <span className="mt" style={{color:c,letterSpacing:sp}}>{children}</span>
);

function Counter({end,suffix=""}) {
  const [v,setV]=useState(0); const ref=useRef(); const done=useRef(false);
  useEffect(()=>{
    const io=new IntersectionObserver(([e])=>{
      if(!e.isIntersecting||done.current)return; done.current=true;
      const s=Date.now();
      const tick=()=>{ const p=Math.min((Date.now()-s)/1400,1); const e2=1-Math.pow(1-p,3); setV(Math.round(e2*end)); if(p<1)requestAnimationFrame(tick); };
      requestAnimationFrame(tick);
    },{threshold:0.1});
    if(ref.current)io.observe(ref.current);
    return()=>io.disconnect();
  },[end]);
  return <span ref={ref}>{v}{suffix}</span>;
}

function Typewriter({text,speed=20,delay=0}) {
  const [s,setS]=useState(""); const [a,setA]=useState(false); const i=useRef(0);
  useEffect(()=>{
    const t=setTimeout(()=>{
      setA(true);
      const iv=setInterval(()=>{ i.current++; setS(text.slice(0,i.current)); if(i.current>=text.length)clearInterval(iv); },speed);
      return()=>clearInterval(iv);
    },delay);
    return()=>clearTimeout(t);
  },[text,speed,delay]);
  return <>{s}{a&&i.current<text.length&&<span style={{animation:"blink 0.7s infinite",color:C.blue}}>│</span>}</>;
}

